// @latency 1
module sync_fifo_core #(
    parameter WIDTH = 8,
    parameter DEPTH = 3
) (
    input wire clk,
    input wire rst,
    input wire [WIDTH-1:0] in_data,
    input wire in_valid,
    output wire in_ready,
    output wire [WIDTH-1:0] out_data,
    output reg out_valid,
    input wire out_ready
);

    function integer clog2;
        input integer value;
        integer i;
        begin
            value = value - 1;
            for (i = 0; value > 0; i = i + 1)
                value = value >> 1;
            clog2 = (i < 1) ? 1 : i;
        end
    endfunction

    localparam PTR_WIDTH = clog2(DEPTH);
    localparam COUNT_WIDTH = clog2(DEPTH + 1);

    reg [WIDTH-1:0] memory [0:DEPTH-1];
    reg [WIDTH-1:0] head;
    reg [PTR_WIDTH-1:0] read_ptr;
    reg [PTR_WIDTH-1:0] write_ptr;
    reg [COUNT_WIDTH-1:0] occupancy;

    wire [PTR_WIDTH-1:0] next_read_ptr;
    wire push;
    wire pop;

    assign next_read_ptr =
        (read_ptr == DEPTH - 1) ? {PTR_WIDTH{1'b0}} : read_ptr + 1'b1;

    assign in_ready = (occupancy < DEPTH) || out_ready;
    assign out_data = head;

    assign push = in_valid && in_ready;
    assign pop = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            read_ptr <= 0;
            write_ptr <= 0;
            occupancy <= 0;
            out_valid <= 1'b0;
        end else begin
            if (push) begin
                memory[write_ptr] <= in_data;
                if (write_ptr == DEPTH - 1)
                    write_ptr <= 0;
                else
                    write_ptr <= write_ptr + 1'b1;
            end

            if (pop) begin
                if (read_ptr == DEPTH - 1)
                    read_ptr <= 0;
                else
                    read_ptr <= read_ptr + 1'b1;
            end

            if (push && (occupancy == 0))
                head <= in_data;
            else if (pop && (occupancy == 1)) begin
                if (push)
                    head <= in_data;
            end else if (pop)
                head <= memory[next_read_ptr];

            case ({push, pop})
                2'b10: begin
                    occupancy <= occupancy + 1'b1;
                    out_valid <= 1'b1;
                end
                2'b01: begin
                    occupancy <= occupancy - 1'b1;
                    out_valid <= (occupancy != 1);
                end
                default: occupancy <= occupancy;
            endcase
        end
    end

endmodule

